using unluac.parse;

namespace unluac.decompile
{
	public static class VariableFinder
	{
		private class RegisterState { public bool temporary; public bool local; public bool read; public bool written; }
		private class RegisterStates { private readonly RegisterState[][] states; private readonly int registers; public RegisterStates(int registers, int lines) { this.registers = registers; states = new RegisterState[lines][]; for (int l = 0; l < lines; l++) { states[l] = new RegisterState[registers]; for (int r = 0; r < registers; r++) states[l][r] = new RegisterState(); } } public RegisterState get(int register, int line) => states[line - 1][register]; public void setLocal(int register, int line) { for (int r = 0; r <= register; r++) get(r, line).local = true; } public void setTemporary(int register, int line) { for (int r = register; r < registers; r++) get(r, line).temporary = true; } }
		private static bool IsConstantReference(int value) => (value & 0x100) != 0;
		public static Declaration[] process(Decompiler d, int args, int registers)
		{
			var code = d.code; var states = new RegisterStates(registers, code.length()); var skip = new bool[code.length()]; for (int line = 1; line <= code.length(); line++) { if (skip[line - 1]) continue; switch (code.op(line)) { case Op.MOVE: states.get(code.A(line), line).written = true; states.get(code.B(line), line).read = true; states.setLocal(Math.Min(code.A(line), code.B(line)), line); break; case Op.LOADK: case Op.LOADBOOL: case Op.GETUPVAL: case Op.GETGLOBAL: case Op.NEWTABLE: case Op.NEWTABLE50: states.get(code.A(line), line).written = true; break; case Op.LOADNIL: for (int reg = code.A(line); reg <= code.B(line); reg++) { states.get(reg, line).written = true; } break; case Op.GETTABLE: states.get(code.A(line), line).written = true; if (!IsConstantReference(code.B(line))) states.get(code.B(line), line).read = true; if (!IsConstantReference(code.C(line))) states.get(code.C(line), line).read = true; break; case Op.SETGLOBAL: case Op.SETUPVAL: states.get(code.A(line), line).read = true; break; case Op.SETTABLE: case Op.ADD: case Op.SUB: case Op.MUL: case Op.DIV: case Op.MOD: case Op.POW: states.get(code.A(line), line).read = true; if (!IsConstantReference(code.B(line))) states.get(code.B(line), line).read = true; if (!IsConstantReference(code.C(line))) states.get(code.C(line), line).read = true; break; case Op.SELF: states.get(code.A(line), line).written = true; states.get(code.A(line) + 1, line).written = true; states.get(code.B(line), line).read = true; if (!IsConstantReference(code.C(line))) states.get(code.C(line), line).read = true; break; case Op.UNM: case Op.NOT: case Op.LEN: states.get(code.A(line), line).written = true; states.get(code.B(line), line).read = true; break; case Op.CONCAT: states.get(code.A(line), line).written = true; for (int reg = code.B(line); reg <= code.C(line); reg++) { states.get(reg, line).read = true; states.setTemporary(reg, line); } break; case Op.SETLIST: states.setTemporary(code.A(line) + 1, line); break; case Op.EQ: case Op.LT: case Op.LE: if (!IsConstantReference(code.B(line))) states.get(code.B(line), line).read = true; if (!IsConstantReference(code.C(line))) states.get(code.C(line), line).read = true; break; case Op.TEST: states.get(code.A(line), line).read = true; break; case Op.TESTSET: states.get(code.A(line), line).written = true; states.get(code.B(line), line).read = true; break; case Op.CLOSURE: { LFunction f = d.function.functions[code.Bx(line)]; foreach (var upvalue in f.upvalues) { if (upvalue.instack) states.setLocal(upvalue.idx, line); } break; } case Op.CALL: case Op.TAILCALL: { int B = code.B(line); int C = code.C(line); if (code.op(line) != Op.TAILCALL) { if (C >= 2) { for (int reg = code.A(line); reg <= code.A(line) + C - 2; reg++) { states.get(reg, line).written = true; } } } for (int reg = code.A(line); reg <= code.A(line) + B - 1; reg++) { states.get(code.A(line), line).read = true; states.setTemporary(code.A(line), line); } if (C >= 2) { int nline = line + 1; int reg2 = code.A(line) + C - 2; while (reg2 >= code.A(line) && nline <= code.length()) { if (code.op(nline) == Op.MOVE && code.B(nline) == reg2) { states.get(code.A(nline), nline).written = true; states.get(code.B(nline), nline).read = true; states.setLocal(code.A(nline), nline); skip[nline - 1] = true; } reg2--; nline++; } } break; } } }
			var declList = new List<Declaration>(registers); for (int register = 0; register < registers; register++)
			{
				string id = "L"; bool local = false; bool temporary = false; int read = 0; int written = 0; if (register < args) { local = true; id = "A"; }
				if (!local && !temporary) { for (int line = 1; line <= code.length(); line++) { var state = states.get(register, line); if (state.local) local = true; if (state.temporary) temporary = true; if (state.read) read++; if (state.written) written++; } }
				if (!local && !temporary) { if (read >= 2 || read == 0) local = true; }
				if (local) { var decl = new Declaration(id + register + "_" + _lc, 0, code.length() + d.getVersion().getOuterBlockScopeAdjustment()); decl.register = register; _lc++; declList.Add(decl); }
			}
			return declList.ToArray();
		}
		private static int _lc = 0;
	}
}